const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaMicrophone, FaDog, FaHome, FaBell, FaBrain, FaChartBar, FaCheckCircle, FaCogs, FaDatabase, FaLayerGroup } = require("react-icons/fa");
const { MdSecurity, MdVolumeUp } = require("react-icons/md");

async function iconToBase64(IconComponent, color = "#FFFFFF", size = 256) {
  const svg = ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette — deep navy + teal accent (tech feel)
const C = {
  navy:      "0A1628",
  navyMid:   "0D2137",
  navyLight: "1A3A5C",
  teal:      "00B4D8",
  tealLight: "48CAE4",
  white:     "FFFFFF",
  offWhite:  "E8F4F8",
  gray:      "8EABBE",
  grayLight: "B8D0DC",
  green:     "06D6A0",
  orange:    "F4A261",
  red:       "EF476F",
  yellow:    "FFD166",
};

const makeShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 3, angle: 45, opacity: 0.18 });

async function buildPPT() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Aditya Sharma";
  pres.title = "Dog Emotion & Scenario Detection System";

  // ─────────────────────────────────────────────────────────
  // SLIDE 1 — Title
  // ─────────────────────────────────────────────────────────
  {
    let s = pres.addSlide();
    s.background = { color: C.navy };

    // Large teal accent circle top-right
    s.addShape(pres.shapes.OVAL, { x: 7.5, y: -1.5, w: 4, h: 4, fill: { color: C.teal, transparency: 85 }, line: { color: C.teal, transparency: 85 } });
    s.addShape(pres.shapes.OVAL, { x: -1, y: 3.5, w: 3, h: 3, fill: { color: C.tealLight, transparency: 88 }, line: { color: C.tealLight, transparency: 88 } });

    const dogIcon = await iconToBase64(FaDog, C.teal, 512);
    s.addImage({ data: dogIcon, x: 0.55, y: 0.8, w: 1.1, h: 1.1 });

    s.addText("Dog Emotion & Scenario", { x: 0.5, y: 2.1, w: 9, h: 0.8, fontSize: 38, bold: true, color: C.white, fontFace: "Calibri", margin: 0 });
    s.addText("Detection System", { x: 0.5, y: 2.85, w: 9, h: 0.7, fontSize: 38, bold: true, color: C.teal, fontFace: "Calibri", margin: 0 });
    s.addText("AI/ML Internship — Hubble Connected", { x: 0.5, y: 3.7, w: 9, h: 0.4, fontSize: 16, color: C.gray, fontFace: "Calibri", margin: 0 });
    s.addText("Aditya Sharma  |  June 2026 – Present", { x: 0.5, y: 4.15, w: 9, h: 0.35, fontSize: 14, color: C.grayLight, fontFace: "Calibri", margin: 0 });

    s.addNotes("Introduce yourself and the project. This is a pet camera app that uses AI to detect dog emotions and trigger smart notifications.");
  }

  // ─────────────────────────────────────────────────────────
  // SLIDE 2 — Problem Statement
  // ─────────────────────────────────────────────────────────
  {
    let s = pres.addSlide();
    s.background = { color: C.navy };

    s.addText("Problem Statement", { x: 0.5, y: 0.35, w: 9, h: 0.6, fontSize: 28, bold: true, color: C.teal, fontFace: "Calibri", margin: 0 });

    const problems = [
      { icon: FaDog,    color: C.teal,   title: "What is the dog feeling?",       desc: "Owners away from home can't tell if their dog is anxious, aggressive, playful, or bored" },
      { icon: FaBell,   color: C.orange, title: "When should owner be notified?",  desc: "Smart cameras need context — not every bark is an emergency" },
      { icon: FaBrain,  color: C.green,  title: "Can audio alone tell the story?", desc: "Combine dog emotion + environmental sounds to infer what scenario is unfolding" },
    ];

    for (let i = 0; i < problems.length; i++) {
      const p = problems[i];
      const y = 1.15 + i * 1.3;
      const iconData = await iconToBase64(p.icon, p.color, 256);

      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: 0.4, y: y, w: 9.2, h: 1.1,
        fill: { color: C.navyLight },
        line: { color: C.navyLight },
        shadow: makeShadow(), rectRadius: 0.08
      });
      s.addImage({ data: iconData, x: 0.65, y: y + 0.3, w: 0.5, h: 0.5 });
      s.addText(p.title, { x: 1.35, y: y + 0.08, w: 7.8, h: 0.38, fontSize: 15, bold: true, color: C.white, fontFace: "Calibri", margin: 0 });
      s.addText(p.desc,  { x: 1.35, y: y + 0.48, w: 7.8, h: 0.5,  fontSize: 12, color: C.gray, fontFace: "Calibri", margin: 0 });
    }

    s.addNotes("The goal is to help pet owners understand what their dog is feeling even when away. Not just bark detection — but full context.");
  }

  // ─────────────────────────────────────────────────────────
  // SLIDE 3 — System Architecture
  // ─────────────────────────────────────────────────────────
  {
    let s = pres.addSlide();
    s.background = { color: C.navy };

    s.addText("System Architecture", { x: 0.5, y: 0.3, w: 9, h: 0.55, fontSize: 28, bold: true, color: C.teal, fontFace: "Calibri", margin: 0 });
    s.addText("Two-model pipeline running on every 3-second audio chunk", { x: 0.5, y: 0.85, w: 9, h: 0.3, fontSize: 13, color: C.gray, fontFace: "Calibri", margin: 0 });

    // Flow boxes
    const boxes = [
      { label: "Audio Input\n(16kHz Mono)", sub: "3-sec chunks", color: C.navyLight, x: 0.3, y: 1.3, w: 1.9 },
      { label: "Dog Emotion\nModel", sub: "WavLM + RF", color: "1A4A6C", x: 2.55, y: 1.3, w: 1.9 },
      { label: "Env Sound\nModel", sub: "Acoustic + RF", color: "1A4A6C", x: 2.55, y: 3.05, w: 1.9 },
      { label: "Scenario\nEngine", sub: "5 State Machines", color: "0D3D5C", x: 4.85, y: 2.1, w: 1.9 },
      { label: "Notification", sub: "Owner's Phone", color: "0A5240", x: 7.15, y: 2.1, w: 1.9 },
    ];

    for (const b of boxes) {
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: b.x, y: b.y, w: b.w, h: 1.0,
        fill: { color: b.color }, line: { color: C.teal, width: 1.5 },
        shadow: makeShadow(), rectRadius: 0.1
      });
      s.addText(b.label, { x: b.x, y: b.y + 0.08, w: b.w, h: 0.58, fontSize: 12, bold: true, color: C.white, fontFace: "Calibri", align: "center", margin: 0 });
      s.addText(b.sub,   { x: b.x, y: b.y + 0.66, w: b.w, h: 0.28, fontSize: 10, color: C.teal, fontFace: "Calibri", align: "center", margin: 0 });
    }

    // Arrows
    const arrowOpts = { line: { color: C.teal, width: 2 }, fill: { color: C.teal } };
    // audio → dog
    s.addShape(pres.shapes.LINE, { x: 2.2, y: 1.8, w: 0.35, h: 0, line: { color: C.teal, width: 2 } });
    // audio → env
    s.addShape(pres.shapes.LINE, { x: 2.2, y: 1.8, w: 0.35, h: 1.75, line: { color: C.teal, width: 2 } });
    // dog → scenario
    s.addShape(pres.shapes.LINE, { x: 4.45, y: 1.8, w: 0.4, h: 0.75, line: { color: C.teal, width: 2 } });
    // env → scenario
    s.addShape(pres.shapes.LINE, { x: 4.45, y: 3.55, w: 0.4, h: -0.95, line: { color: C.teal, width: 2 } });
    // scenario → notification
    s.addShape(pres.shapes.LINE, { x: 6.75, y: 2.6, w: 0.4, h: 0, line: { color: C.teal, width: 2 } });

    // Labels on arrows
    s.addText("High/Low/Playful", { x: 4.5, y: 1.55, w: 2, h: 0.3, fontSize: 9, color: C.tealLight, fontFace: "Calibri", margin: 0 });
    s.addText("door/siren/speech", { x: 4.5, y: 3.1,  w: 2, h: 0.3, fontSize: 9, color: C.tealLight, fontFace: "Calibri", margin: 0 });

    s.addNotes("Both models run in parallel on every 3-second chunk. Dog emotion + environmental sound fed into scenario engine.");
  }

  // ─────────────────────────────────────────────────────────
  // SLIDE 4 — Data Pipeline & Cleaning
  // ─────────────────────────────────────────────────────────
  {
    let s = pres.addSlide();
    s.background = { color: C.navy };

    s.addText("Data Pipeline & Leakage Removal", { x: 0.5, y: 0.3, w: 9, h: 0.55, fontSize: 28, bold: true, color: C.teal, fontFace: "Calibri", margin: 0 });

    // Before / After stat cards
    s.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 0.4, y: 1.0, w: 2.8, h: 1.5, fill: { color: C.navyLight }, line: { color: C.red }, rectRadius: 0.1, shadow: makeShadow() });
    s.addText("BEFORE", { x: 0.4, y: 1.05, w: 2.8, h: 0.3, fontSize: 11, bold: true, color: C.red, align: "center", fontFace: "Calibri", margin: 0 });
    s.addText("600", { x: 0.4, y: 1.35, w: 2.8, h: 0.55, fontSize: 40, bold: true, color: C.white, align: "center", fontFace: "Calibri", margin: 0 });
    s.addText("Anxiety files (fake)", { x: 0.4, y: 1.9, w: 2.8, h: 0.28, fontSize: 11, color: C.gray, align: "center", fontFace: "Calibri", margin: 0 });

    s.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 3.5, y: 1.0, w: 2.8, h: 1.5, fill: { color: C.navyLight }, line: { color: C.green }, rectRadius: 0.1, shadow: makeShadow() });
    s.addText("AFTER", { x: 3.5, y: 1.05, w: 2.8, h: 0.3, fontSize: 11, bold: true, color: C.green, align: "center", fontFace: "Calibri", margin: 0 });
    s.addText("25", { x: 3.5, y: 1.35, w: 2.8, h: 0.55, fontSize: 40, bold: true, color: C.white, align: "center", fontFace: "Calibri", margin: 0 });
    s.addText("Genuine unique files", { x: 3.5, y: 1.9, w: 2.8, h: 0.28, fontSize: 11, color: C.gray, align: "center", fontFace: "Calibri", margin: 0 });

    s.addText("100% → 30%\nFake Accuracy Fixed", { x: 6.6, y: 1.0, w: 2.9, h: 1.5, fontSize: 16, bold: true, color: C.yellow, align: "center", valign: "middle", fontFace: "Calibri", margin: 0 });

    // 3-layer dedup
    s.addText("3-Layer Deduplication Pipeline", { x: 0.4, y: 2.7, w: 9, h: 0.35, fontSize: 14, bold: true, color: C.white, fontFace: "Calibri", margin: 0 });

    const layers = [
      { num: "1", title: "SHA-256 Hash", desc: "Exact bitwise duplicates — same file different name" },
      { num: "2", title: "Spectral Fingerprint", desc: "MFCC + Chroma cosine similarity ≥ 0.97 — same source slices" },
      { num: "3", title: "Noise Floor Fingerprint", desc: "Sub-300Hz power spectrum — same recording session" },
    ];

    for (let i = 0; i < layers.length; i++) {
      const l = layers[i];
      const y = 3.15 + i * 0.72;
      s.addShape(pres.shapes.OVAL, { x: 0.4, y: y + 0.05, w: 0.5, h: 0.5, fill: { color: C.teal }, line: { color: C.teal } });
      s.addText(l.num, { x: 0.4, y: y + 0.05, w: 0.5, h: 0.5, fontSize: 14, bold: true, color: C.navy, align: "center", valign: "middle", fontFace: "Calibri", margin: 0 });
      s.addText(l.title, { x: 1.05, y: y, w: 2.8, h: 0.32, fontSize: 12, bold: true, color: C.white, fontFace: "Calibri", margin: 0 });
      s.addText(l.desc,  { x: 1.05, y: y + 0.3, w: 8, h: 0.32, fontSize: 11, color: C.gray, fontFace: "Calibri", margin: 0 });
    }

    s.addNotes("This was the biggest initial challenge — the dataset had severe source leakage. We built 3-layer dedup using SHA-256, spectral fingerprinting, and noise floor analysis.");
  }

  // ─────────────────────────────────────────────────────────
  // SLIDE 5 — Dog Emotion Model
  // ─────────────────────────────────────────────────────────
  {
    let s = pres.addSlide();
    s.background = { color: C.navy };

    s.addText("Dog Emotion Classifier", { x: 0.5, y: 0.3, w: 9, h: 0.55, fontSize: 28, bold: true, color: C.teal, fontFace: "Calibri", margin: 0 });

    // Feature stack
    s.addText("Feature Extraction", { x: 0.4, y: 0.95, w: 4.2, h: 0.35, fontSize: 14, bold: true, color: C.white, fontFace: "Calibri", margin: 0 });

    const feats = [
      { label: "WavLM Embeddings", val: "3072-dim", color: C.teal, desc: "Last 4 hidden layers mean-pooled" },
