    ];

    for (let i = 0; i < feats.length; i++) {
      const f = feats[i];
      const y = 1.4 + i * 0.75;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 0.4, y, w: 4.2, h: 0.62, fill: { color: C.navyLight }, line: { color: f.color, width: 1.5 }, rectRadius: 0.07, shadow: makeShadow() });
      s.addText(f.label, { x: 0.55, y: y + 0.04, w: 2.5, h: 0.3, fontSize: 12, bold: true, color: C.white, fontFace: "Calibri", margin: 0 });
      s.addText(f.val,   { x: 3.1,  y: y + 0.04, w: 1.3, h: 0.3, fontSize: 12, bold: true, color: f.color, align: "right", fontFace: "Calibri", margin: 0 });
      s.addText(f.desc,  { x: 0.55, y: y + 0.32, w: 3.9, h: 0.25, fontSize: 10, color: C.gray, fontFace: "Calibri", margin: 0 });
    }

    // Total
