{"language": "bash", "code": "cat > /home/claude/ppt.js << 'EOF'
const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaMicrophone, FaDog, FaHome, FaBell, FaBrain, FaChartBar, FaCheckCircle, FaCogs, FaDatabase, FaLayerGroup } = require("react-icons/fa");
const { MdSecurity, MdVolumeUp } = require("react-icons/md");

async function iconToBase64(IconComponent, color = "#FFFFFF", size = 256) {
  const svg = ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette — deep navy + teal accent (tech feel)
const C = {
  navy:      "0A1628",
  navyMid:   "0D2137",
  navyLight: "1A3A5C",
  teal:      "00B4D8",
  tealLight: "48CAE4",
  white:     "FFFFFF",
  offWhite:  "E8F4F8",
  gray:      "8EABBE",
  grayLight: "B8D0DC",
  green:     "06D6A0",
  orange:    "F4A261",
  red:       "EF476F",
  yellow:    "FFD166",
};

const makeShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 3, angle: 45, opacity: 0.18 });

async function buildPPT() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Aditya Sharma";
  pres.title = "Dog Emotion & Scenario Detection System";

  // ─────────────────────────────────────────────────────────
  // SLIDE 1 — Title
  // ─────────────────────────────────────────────────────────
  {
    let s = pres.addSlide();
    s.background = { color: C.navy };

    // Large teal accent circle top-right
    s.addShape(pres.shapes.OVAL, { x: 7.5, y: -1.5, w: 4, h: 4, fill: { color: C.teal, transparency: 85 }, line: { color: C.teal, transparency: 85 } });
    s.addShape(pres.shapes.OVAL, { x: -1, y: 3.5, w: 3, h: 3, fill: { color: C.tealLight, transparency: 88 }, line: { color: C.tealLight, transparency: 88 } });

    const dogIcon = await iconToBase64(FaDog, C.teal, 512);
    s.addImage({ data: dogIcon, x: 0.55, y: 0.8, w: 1.1, h: 1.1 });

    s.addText("Dog Emotion & Scenario", { x: 0.5, y: 2.1, w: 9, h: 0.8, fontSize: 38, bold: true, color: C.white, fontFace: "Calibri", margin: 0 });
    s.addText("Detection System", { x: 0.5, y: 2.85, w: 9, h: 0.7, fontSize: 38, bold: true, color: C.teal, fontFace: "Calibri", margin: 0 });
    s.addText("AI/ML Internship — Hubble Connected", { x: 0.5, y: 3.7, w: 9, h: 0.4, fontSize: 16, color: C.gray, fontFace: "Calibri", margin: 0 });
    s.addText("Aditya Sharma  |  June 2026 – Present", { x: 0.5, y: 4.15, w: 9, h: 0.35, fontSize: 14, color: C.grayLight, fontFace: "Calibri", margin: 0 });

    s.addNotes("Introduce yourself and the project. This is a pet camera app that uses AI to detect dog emotions and trigger smart notifications.");
  }

  // ─────────────────────────────────────────────────────────
  // SLIDE 2 — Problem Statement
  // ─────────────────────────────────────────────────────────
  {
    let s = pres.addSlide();
    s.background = { color: C.navy };

    s.addText("Problem Statement", { x: 0.5, y: 0.35, w: 9, h: 0.6, fontSize: 28, bold: true, color: C.teal, fontFace: "Calibri", margin: 0 });

    const problems = [
      { icon: FaDog,    color: C.teal,   title: "What is the dog feeling?",       desc: "Owners away from home can't tell if their dog is anxious, aggressive, playful, or bored" },
      { icon: FaBell,   color: C.orange, title: "When should owner be notified?",  desc: "Smart cameras need context — not every bark is an emergency" },
      { icon: FaBrain,  color: C.green,  title: "Can audio alone tell the story?", desc: "Combine dog emotion + environmental sounds to infer what scenario is unfolding" },
    ];

    for (let i = 0; i < problems.length; i++) {
