      const y = 1.15 + i * 1.3;
      const iconData = await iconToBase64(p.icon, p.color, 256);

      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: 0.4, y: y, w: 9.2, h: 1.1,
        fill: { color: C.navyLight },
        line: { color: C.navyLight },
        shadow: makeShadow(), rectRadius: 0.08
      });
      s.addImage({ data: iconData, x: 0.65, y: y + 0.3, w: 0.5, h: 0.5 });
      s.addText(p.title, { x: 1.35, y: y + 0.08, w: 7.8, h: 0.38, fontSize: 15, bold: true, color: C.white, fontFace: "Calibri", margin: 0 });
      s.addText(p.desc,  { x: 1.35, y: y + 0.48, w: 7.8, h: 0.5,  fontSize: 12, color: C.gray, fontFace: "Calibri", margin: 0 });
    }

    s.addNotes("The goal is to help pet owners understand what their dog is feeling even when away. Not just bark detection — but full context.");
  }

  // ─────────────────────────────────────────────────────────
  // SLIDE 3 — System Architecture
  // ─────────────────────────────────────────────────────────
  {
    let s = pres.addSlide();
    s.background = { color: C.navy };

    s.addText("System Architecture", { x: 0.5, y: 0.3, w: 9, h: 0.55, fontSize: 28, bold: true, color: C.teal, fontFace: "Calibri", margin: 0 });
    s.addText("Two-model pipeline running on every 3-second audio chunk", { x: 0.5, y: 0.85, w: 9, h: 0.3, fontSize: 13, color: C.gray, fontFace: "Calibri", margin: 0 });

    // Flow boxes
    const boxes = [
      { label: "Audio Input\n(16kHz Mono)", sub: "3-sec chunks", color: C.navyLight, x: 0.3, y: 1.3, w: 1.9 },
