      { label: "Scenario\nEngine", sub: "5 State Machines", color: "0D3D5C", x: 4.85, y: 2.1, w: 1.9 },
      { label: "Notification", sub: "Owner's Phone", color: "0A5240", x: 7.15, y: 2.1, w: 1.9 },
    ];

    for (const b of boxes) {
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: b.x, y: b.y, w: b.w, h: 1.0,
        fill: { color: b.color }, line: { color: C.teal, width: 1.5 },
        shadow: makeShadow(), rectRadius: 0.1
      });
      s.addText(b.label, { x: b.x, y: b.y + 0.08, w: b.w, h: 0.58, fontSize: 12, bold: true, color: C.white, fontFace: "Calibri", align: "center", margin: 0 });
      s.addText(b.sub,   { x: b.x, y: b.y + 0.66, w: b.w, h: 0.28, fontSize: 10, color: C.teal, fontFace: "Calibri", align: "center", margin: 0 });
    }

    // Arrows
    const arrowOpts = { line: { color: C.teal, width: 2 }, fill: { color: C.teal } };
    // audio → dog
