**Key insight:** For each ride i, find the 90th percentile (nearest-rank) of all fares in window (t_i - 300, t_i] (half-open, includes current ride). Flag as 1 if fare **strictly greater** than that 90th percentile. Windows with <10 rides always output 0.

The 90th percentile by nearest-rank = fare at index `ceil(0.9 * n) - 1` = index `floor(0.9*n - epsilon)` = basically the `⌈0.9n⌉`-th smallest. Since for n≤9, that index = n-1 (the max), the current ride can never exceed it strictly → always 0.

**Approach:** Sliding window with a sorted multiset. For each ride, add it, remove rides outside the window, then find the 90th percentile element.

Finding kth element in a multiset efficiently: use an order-statistics approach with a Fenwick tree on compressed fare values — since fares can be up to 1e9 but N≤200000, we coordinate compress.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <deque>
using namespace std;

// Fenwick tree for order statistics
struct BIT {
    int n;
    vector<int> tree;
    BIT(int n) : n(n), tree(n+1, 0) {}
    void update(int i, int v) { for(i++; i<=n; i+=i&-i) tree[i]+=v; }
    int query(int i) { int s=0; for(i++; i>0; i-=i&-i) s+=tree[i]; return s; }
    // find smallest index with prefix sum >= k (1-indexed k)
    int kth(int k) {
        int pos=0;
        for(int pw=1<<17; pw; pw>>=1)
            if(pos+pw<=n && tree[pos+pw]<k)
                pos+=pw, k-=tree[pos];
        return pos; // 0-indexed compressed
    }
};

struct InputData {
    int N;
    vector<long long> times;
    vector<long long> fares;
};

static bool parse_input(InputData &D) {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    if(!(cin >> D.N)) return false;
    D.times.assign(D.N, 0);
    D.fares.assign(D.N, 0);
    for(int i=0; i<D.N; ++i) cin >> D.times[i] >> D.fares[i];
    return true;
}

static void format_output(const vector<int> &flags) {
    for(int f : flags) cout << f << "\n";
}

static vector<int> solve(const InputData &D) {
    int N = D.N;
    vector<int> flags(N, 0);

    // Coordinate compress fares
    vector<long long> sorted_fares = D.fares;
    sort(sorted_fares.begin(), sorted_fares.end());
    sorted_fares.erase(unique(sorted_fares.begin(), sorted_fares.end()), sorted_fares.end());
    int M = sorted_fares.size();

    auto compress = [&](long long v) {
        return (int)(lower_bound(sorted_fares.begin(), sorted_fares.end(), v) - sorted_fares.begin());
    };

    BIT bit(M);
    deque<int> window; // indices of rides in current window
    int left = 0;
    int window_size = 0;

    for(int i=0; i<N; ++i) {
        // Add current ride
        int ci = compress(D.fares[i]);
        bit.update(ci, 1);
        window_size++;
        window.push_back(i);

        // Remove rides outside (t_i - 300, t_i] i.e. timestamp <= t_i - 300
        while(!window.empty() && D.times[window.front()] <= D.times[i] - 300) {
            int rem = window.front(); window.pop_front();
            bit.update(compress(D.fares[rem]), -1);
            window_size--;
        }

        int n = window_size;
        if(n < 10) {
            flags[i] = 0;
            continue;
        }

        // 90th percentile: ceil(0.9 * n)-th smallest, 1-indexed
        int k = (int)ceil(0.9 * n); // = floor(0.9*n) if 0.9n is integer, else ceil
        // nearest-rank: ceil(0.9 * n)
        // Use integer arithmetic: ceil(9*n / 10)
        k = (9*n + 9) / 10; // ceil(9n/10)

        int perc_idx = bit.kth(k); // 0-indexed in compressed array
        long long perc_fare = sorted_fares[perc_idx];

        flags[i] = (D.fares[i] > perc_fare) ? 1 : 0;
    }

    return flags;
}

int main() {
    InputData D;
    if(!parse_input(D)) return 0;
    vector<int> flags = solve(D);
    format_output(flags);
    return 0;
}
```

**Key points:**
- BIT (Fenwick tree) gives O(log N) kth-element queries
- Overall O(N log N)
- Window removal: strictly `timestamp <= t_i - 300` gets removed (half-open window excludes that boundary)
- `ceil(0.9 * n)` computed as `(9*n + 9) / 10` to avoid floating point issues
- For n < 10, always output 0 (by design from the problem)

